      "template": "/Users/yong/.codex/worktrees/00b1/lemmadeck/.intentfold/tickets/STEMROBIN-181/tmp/d039-10p-n35-author/work-en/adapt/10p/modern-us-neutral/lessons/phy10-c1-s4-n35/lesson.template.json",
